INSERT INTO public.missions (id, province_id, title, description, content, level, estimated_time, nc_reward, tier, region, created_at)
VALUES (
    -- OLD INVALID: 123ABCDE-F4G5-4293-0123-456789012DEF (G is bad)
    '123ABCDE-F4A5-4293-0123-456789012DEF', 'RO', 'Volti Inesistenti',
    'Riesci a distinguere una persona vera da una generata dall''IA?',
    E'# Riconoscere i Deepfake Visivi\n\nL''IA generativa (GAN) crea volti fotorealistici.\nMa spesso lascia tracce:\n\n*   Orecchie diverse o malformate.\n*   Sfondo confuso o incoerente.\n*   Capelli che sfumano nel nulla.\n*   Denti troppo perfetti o troppi.\n\nGuarda i dettagli, non l''insieme.',
