INSERT INTO public.mission_questions (mission_id, text, type, options, correct_answer, explanation) VALUES
('123ABCDE-F4A5-4293-0123-456789012DEF', 'Cos''è un Deepfake?', 'multiple_choice', '["Un lago profondo", "Un contenuto multimediale (video/audio/foto) manipolato o generato dall''IA per sembrare reale", "Un errore", "Una maschera"]', 1, 'Deep Learning + Fake.'),
('123ABCDE-F4A5-4293-0123-456789012DEF', 'Quale dettaglio tradisce spesso un volto generato da IA?', 'multiple_choice', '["Il colore degli occhi", "Asimmetrie negli occhiali, orecchie strane, o sfondi onirici/sfocati in modo innaturale", "Il naso", "La bocca"]', 1, 'L''IA fatica con la coerenza geometrica degli accessori.'),
('123ABCDE-F4A5-4293-0123-456789012DEF', 'A cosa servono i profili con volti generati da IA?', 'multiple_choice', '["Per bellezza", "Per creare account falsi (bot) credibili sui social per disinformazione o truffe", "Per i film", "Per gioco"]', 1, 'Siti come "ThisPersonDoesNotExist" sono usati massicciamente dai bot.'),
('123ABCDE-F4A5-4293-0123-456789012DEF', 'Il Deepfake è sempre illegale?', 'multiple_choice', '["Sì", "No, è una tecnologia (usata anche al cinema). Diventa illegale se usata per diffamazione, frode o revenge porn", "Solo in Italia", "Mai"]', 1, 'La tecnologia è neutra, l''uso no.'),
('123ABCDE-F4A5-4293-0123-456789012DEF', 'Possiamo fidarci ciecamente delle foto online?', 'multiple_choice', '["Sì, se sono HD", "No. L''era del \"se lo vedo ci credo\" è finita. Serve verifica della fonte", "Solo se a colori", "Sempre"]', 1, 'Dobbiamo reimparare a guardare.');


