INSERT INTO public.mission_questions (mission_id, text, type, options, correct_answer, explanation) VALUES
('678FAB12-C9D0-4415-2345-6789012341AB', 'Cosa significa "Clean Desk Policy"?', 'multiple_choice', '["Pulire con lo spray", "Politica aziendale che impone di rimuovere documenti sensibili e supporti dalla scrivania quando non si è al posto", "Avere scrivanie di vetro", "Non lavorare"]', 1, 'Riduce il rischio di furto di informazioni visivo.'),
('678FAB12-C9D0-4415-2345-6789012341AB', 'Dove buttare i documenti sensibili?', 'multiple_choice', '["Nel cestino normale", "Nel tritadocumenti (Shredder) o negli appositi contenitori di sicurezza", "Dalla finestra", "Farne aeroplanini"]', 1, 'Il "Dumpster Diving" (frugare nella spazzatura) è una tecnica reale.'),
('678FAB12-C9D0-4415-2345-6789012341AB', 'Perché le lavagne bianche sono pericolose?', 'multiple_choice', '["Puzzano di pennarello", "Spesso rimangono schemi di rete, password o progetti segreti disegnati sopra dopo le riunioni", "Sono brutte", "Cadono"]', 1, 'Cancella sempre la lavagna dopo la riunione.'),
('678FAB12-C9D0-4415-2345-6789012341AB', 'Scrivere la password sotto la tastiera è sicuro?', 'multiple_choice', '["Sì, nessuno guarda lì", "No. È il primo posto (insieme al post-it sul monitor) dove un attaccante guarda", "Geniale", "Solo a matita"]', 1, 'Usa un Password Manager, non i post-it.'),
('678FAB12-C9D0-4415-2345-6789012341AB', 'Le stampanti comuni sono a rischio?', 'multiple_choice', '["No", "Sì, se stampi e dimentichi il foglio lì, chiunque può leggerlo", "Stampano solo", "Non funzionano mai"]', 1, 'Ritira subito le tue stampe "Follow-me printing".');
